#include <stdio.h>
#include <stdlib.h>
#include <string.h>
// input: nseg, seglen[], n=2m, G (n x n) rowmajor, fac[e] per edge; output c[T] for T in 2^nseg
int nseg,n; int *seglen,*segoff; double *G,*fac,*out; double *buf[64];
void rec(int k,double *M,int dim,double pf,long T){
  if(k==nseg){out[T]=pf;return;}
  int b=2*seglen[k]; int nd=dim-b;
  double *N=buf[k+1];
  // exclude: drop first b rows/cols
  for(int i=0;i<nd;i++) memcpy(N+i*nd,M+(i+b)*dim+b,nd*sizeof(double));
  rec(k+1,N,nd,pf,T);
  // include: eliminate pivots pairwise
  double *A=buf[k+1]; memcpy(A,M,dim*dim*sizeof(double));
  int d=dim; double p=pf;
  for(int e=0;e<seglen[k];e++){
    double a=A[0*d+1]; p*=a*fac[segoff[k]+e];
    int r=d-2; double *B=malloc(r*r*sizeof(double));
    // R + Q^T P^{-1} Q, P^{-1}=[[0,-1/a],[1/a,0]] ; Q rows 0,1 cols 2..
    for(int i=0;i<r;i++){double q0i=A[0*d+i+2],q1i=A[1*d+i+2];
      for(int j=0;j<r;j++){double q0j=A[0*d+j+2],q1j=A[1*d+j+2];
        B[i*r+j]=A[(i+2)*d+j+2]+(-q0i*q1j+q1i*q0j)/a;}}
    memcpy(A,B,r*r*sizeof(double)); free(B); d=r;
  }
  // A now dim nd but buf[k+1] reused by deeper levels -> copy to temp
  double *C=malloc(nd*nd*sizeof(double)+8); memcpy(C,A,nd*nd*sizeof(double));
  rec(k+1,C,nd,p,T|(1L<<k)); free(C);
}
int main(int argc,char**argv){
  FILE*f=fopen(argv[1],"rb"); fread(&nseg,4,1,f); seglen=malloc(4*nseg);segoff=malloc(4*nseg);
  fread(seglen,4,nseg,f); int m=0; for(int i=0;i<nseg;i++){segoff[i]=m;m+=seglen[i];} n=2*m;
  G=malloc(8L*n*n); fread(G,8,(long)n*n,f); fac=malloc(8*m); fread(fac,8,m,f); fclose(f);
  for(int i=0;i<=nseg;i++) buf[i]=malloc(8L*n*n+8);
  out=malloc(8L<<nseg); rec(0,G,n,1.0,0);
  f=fopen(argv[2],"wb"); fwrite(out,8,1L<<nseg,f); fclose(f); return 0;}
EOF
